//! Project verification on a throwaway working copy.
//!
//! Files produced by the assistant are kept as *pending diffs* and are not
//! written to the real project until the user accepts them. To let the assistant
//! compile/test its own work, this module materializes a temporary copy of the
//! project (existing sources + staged generated files) in a scratch directory,
//! detects the project type and runs the relevant build/check commands there.
//!
//! The real project and the diff-review workflow stay completely untouched.

use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use super::fs::run_shell_command_streaming;

/// Maximum time allowed for a single verification command (builds can be slow).
pub const VERIFY_TIMEOUT: Duration = Duration::from_secs(300);

/// Directories never copied into the temp workspace (they are dependencies or
/// build artifacts that the verification commands regenerate themselves).
const IGNORED_DIRS: &[&str] = &[
    "node_modules",
    "target",
    ".git",
    "dist",
    "build",
    ".venv",
    "venv",
    "__pycache__",
    ".angular",
    ".next",
    ".nuxt",
    ".cache",
    "coverage",
    ".idea",
    ".vscode",
    ".rustagent",
];

// ---------------------------------------------------------------------------
// Staging registry: files generated by the assistant during the current turn.
//
// The state itself lives in the process-wide [`crate::session::AgentSession`];
// these helpers are thin delegations kept for the existing call sites.
// ---------------------------------------------------------------------------

fn normalize(p: &str) -> String {
    p.trim().replace('\\', "/")
}

/// Forget every staged file. Called at the start of each assistant turn so the
/// registry never mixes files from unrelated requests.
pub fn clear_staging() {
    crate::session::default_session().clear_staging();
}

/// Register a file generated by the assistant (pending-diff content) so it is
/// included in the temporary verification workspace.
pub fn stage_file(path: &str, content: &str) {
    crate::session::default_session().stage_file(path, content);
}

/// Snapshot of the currently staged files, as `(normalized path, content)`.
pub fn staged_files() -> Vec<(String, String)> {
    crate::session::default_session().staged_files()
}

// ---------------------------------------------------------------------------
// Public entry point
// ---------------------------------------------------------------------------

/// Verify the project located at `cwd` (or inferred from the staged files) on a
/// temporary copy, returning a report meant to be fed back to the model.
pub async fn run_verification(cwd: Option<&str>) -> String {
    run_verification_streaming(cwd, |_| {}).await
}

/// Same as [`run_verification`], but streams each command and its output to
/// `on_output` as it runs, so the UI can display the execution live (terminal
/// style) instead of only showing the final report.
pub async fn run_verification_streaming<F>(cwd: Option<&str>, mut on_output: F) -> String
where
    F: FnMut(&str),
{
    let staged = staged_files();
    let project_root = determine_project_root(cwd, &staged);

    let root_for_task = project_root.clone();
    let staged_for_task = staged.clone();
    let prepared =
        tokio::task::spawn_blocking(move || prepare_workspace(&root_for_task, &staged_for_task))
            .await;

    let (workspace_root, commands) = match prepared {
        Ok(Ok(v)) => v,
        Ok(Err(e)) => return format!("🔎 Vérification impossible : {}", e),
        Err(e) => return format!("🔎 Vérification impossible (tâche interne) : {}", e),
    };

    if commands.is_empty() {
        return format!(
            "🔎 Vérification : aucun projet compilable détecté pour `{}` (pas de Cargo.toml, package.json, tsconfig.json, go.mod, ni fichier .py/.js à vérifier). Copie de travail : `{}`.",
            project_root,
            workspace_root.to_string_lossy().replace('\\', "/")
        );
    }

    let workspace_str = workspace_root.to_string_lossy().to_string();
    let mut report = String::new();
    let mut all_ok = true;
    for cmd in &commands {
        // Affiche la commande AVANT de l'exécuter : l'utilisateur voit ainsi
        // l'exécution défiler en direct, comme dans un terminal.
        on_output(&format!("\n$ {}\n", cmd));
        let (ok, out) = run_shell_command_streaming(
            cmd,
            Some(workspace_str.as_str()),
            VERIFY_TIMEOUT,
            |line| on_output(&format!("{}\n", line)),
        )
        .await;
        if !ok {
            all_ok = false;
        }
        // Affiche le statut de sortie (première ligne du rapport) une fois la
        // commande terminée, pour clore le bloc façon terminal.
        if let Some(status_line) = out.lines().next() {
            on_output(&format!("\n{}\n", status_line));
        }
        report.push_str(&format!("\n$ {}\n{}\n", cmd, out));
    }

    let header = if all_ok {
        format!(
            "🔎 Vérification OK ✅ — le projet `{}` compile / se build sans erreur.",
            project_root
        )
    } else {
        format!(
            "🔎 Vérification ÉCHEC ❌ — des erreurs ont été détectées pour `{}`. Corrige les fichiers concernés avec `edit_file` / `write_file`, puis rappelle `verify_project`.",
            project_root
        )
    };

    format!(
        "{}\n{}\n\n(Copie de travail temporaire `{}` — le projet réel et les diffs en attente n'ont PAS été modifiés.)",
        header,
        report,
        workspace_str.replace('\\', "/")
    )
}

// ---------------------------------------------------------------------------
// Workspace preparation
// ---------------------------------------------------------------------------

fn prepare_workspace(
    project_root: &str,
    staged: &[(String, String)],
) -> Result<(PathBuf, Vec<String>), String> {
    // One temp workspace per project root (cached in the session), so verifying
    // a project never disturbs another in-flight verification.
    let root = crate::session::default_session()
        .workspace_with(project_root, || create_workspace(project_root))?;

    // Overlay the assistant's staged files at their project-relative location.
    for (path, content) in staged {
        let rel = relativize(path, project_root);
        if rel.is_empty() {
            continue;
        }
        let dest = root.join(&rel);
        if let Some(parent) = dest.parent() {
            std::fs::create_dir_all(parent)
                .map_err(|e| format!("création du dossier pour '{}': {}", rel, e))?;
        }
        std::fs::write(&dest, content).map_err(|e| format!("écriture de '{}': {}", rel, e))?;
    }

    let commands = detect_commands(&root);
    Ok((root, commands))
}

fn create_workspace(project_root: &str) -> Result<PathBuf, String> {
    let unique = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let root = std::env::temp_dir().join(format!("rustagent_verify_{}", unique));
    std::fs::create_dir_all(&root).map_err(|e| format!("création du dossier temporaire: {}", e))?;

    let src = Path::new(project_root);
    if src.is_dir() {
        copy_project_tree(src, &root)?;
    }
    Ok(root)
}

fn copy_project_tree(src: &Path, dst: &Path) -> Result<(), String> {
    let entries =
        std::fs::read_dir(src).map_err(|e| format!("lecture de '{}': {}", src.display(), e))?;
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if IGNORED_DIRS.iter().any(|d| d.eq_ignore_ascii_case(&name)) {
            continue;
        }
        let Ok(ft) = entry.file_type() else { continue };
        let to = dst.join(&name);
        if ft.is_dir() {
            std::fs::create_dir_all(&to).ok();
            copy_project_tree(&entry.path(), &to)?;
        } else if ft.is_file() {
            let _ = std::fs::copy(entry.path(), &to);
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Project type detection
// ---------------------------------------------------------------------------

/// Detect the build/check/test commands to run for the project rooted at `root`.
pub fn detect_commands(root: &Path) -> Vec<String> {
    let has = |name: &str| root.join(name).exists();
    let mut commands = Vec::new();

    if has("Cargo.toml") {
        commands.push("cargo check --quiet".to_string());
        commands.push("cargo test --quiet".to_string());
    }

    if has("package.json") {
        commands.push("npm install --no-audit --no-fund --loglevel=error".to_string());
        if read_json_script(root, "build").is_some() {
            commands.push("npm run build".to_string());
        } else if has("tsconfig.json") {
            commands.push("npx --yes tsc --noEmit".to_string());
        } else {
            commands.extend(node_check_commands(root));
        }
        if has_npm_test_script(root) {
            commands.push("npm test --silent".to_string());
        }
    } else if has("tsconfig.json") {
        commands.push("npx --yes tsc --noEmit".to_string());
    }

    if has("go.mod") {
        commands.push("go build ./...".to_string());
        commands.push("go test ./...".to_string());
    }

    let py_files = collect_files(root, &["py"], 25);
    if !py_files.is_empty() {
        commands.push(format!(
            "python -m py_compile {}",
            py_files
                .iter()
                .map(|f| shell_quote(f))
                .collect::<Vec<_>>()
                .join(" ")
        ));
    }
    // Run Python tests only when a conventional test location exists. The
    // standard-library runner needs no extra dependency and exits 0 when it
    // finds no test, so it never produces a false failure.
    if root.join("tests").is_dir() || root.join("test").is_dir() {
        commands.push("python -m unittest discover -q".to_string());
    }

    // Plain JS projects (no package.json) get a per-file syntax check.
    if !has("package.json") {
        commands.extend(node_check_commands(root));
    }

    commands
}

/// Whether `package.json` defines a meaningful `test` script (the `npm init`
/// placeholder "no test specified" is ignored).
fn has_npm_test_script(root: &Path) -> bool {
    read_json_script(root, "test")
        .map(|s| {
            let t = s.to_lowercase();
            !t.trim().is_empty() && !t.contains("no test specified")
        })
        .unwrap_or(false)
}

/// Return one `node --check <file>` command per JavaScript file.
///
/// One command per file (instead of `a; b; c`) is essential: joined with `;`
/// the shell exit status only reflects the *last* check, which would silently
/// hide syntax errors in every earlier file.
fn node_check_commands(root: &Path) -> Vec<String> {
    collect_files(root, &["js", "mjs", "cjs"], 12)
        .iter()
        .map(|f| format!("node --check {}", shell_quote(f)))
        .collect()
}

fn read_json_script(root: &Path, key: &str) -> Option<String> {
    let text = std::fs::read_to_string(root.join("package.json")).ok()?;
    let val: serde_json::Value = serde_json::from_str(&text).ok()?;
    val.get("scripts")
        .and_then(|s| s.get(key))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

fn collect_files(root: &Path, exts: &[&str], max: usize) -> Vec<String> {
    let mut out = Vec::new();
    collect_files_rec(root, root, exts, max, &mut out);
    out
}

fn collect_files_rec(root: &Path, dir: &Path, exts: &[&str], max: usize, out: &mut Vec<String>) {
    if out.len() >= max {
        return;
    }
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        if out.len() >= max {
            return;
        }
        let name = entry.file_name().to_string_lossy().to_string();
        if name.starts_with('.') || IGNORED_DIRS.iter().any(|d| d.eq_ignore_ascii_case(&name)) {
            continue;
        }
        let Ok(ft) = entry.file_type() else { continue };
        let path = entry.path();
        if ft.is_dir() {
            collect_files_rec(root, &path, exts, max, out);
        } else if ft.is_file() {
            let ext = path
                .extension()
                .and_then(|e| e.to_str())
                .unwrap_or("")
                .to_lowercase();
            if exts.iter().any(|e| *e == ext)
                && let Ok(rel) = path.strip_prefix(root)
            {
                out.push(rel.to_string_lossy().replace('\\', "/"));
            }
        }
    }
}

fn shell_quote(s: &str) -> String {
    if s.contains(' ') || s.contains('\'') {
        format!("'{}'", s.replace('\'', "'\\''"))
    } else {
        s.to_string()
    }
}

// ---------------------------------------------------------------------------
// Path helpers
// ---------------------------------------------------------------------------

/// Infer the project root: an explicit `cwd` wins, otherwise the common parent
/// directory of the staged files, otherwise the current directory.
pub fn determine_project_root(cwd: Option<&str>, staged: &[(String, String)]) -> String {
    if let Some(c) = cwd {
        let n = normalize(c);
        let n = n.trim_end_matches('/');
        let n = n.trim_start_matches("./");
        if !n.is_empty() && n != "." && n != "/" {
            return n.to_string();
        }
    }

    let dirs: Vec<Vec<String>> = staged
        .iter()
        .map(|(p, _)| {
            let n = normalize(p);
            let mut parts: Vec<String> = n.split('/').map(|s| s.to_string()).collect();
            parts.pop(); // drop the file name
            parts
        })
        .collect();

    if !dirs.is_empty() {
        let mut common = dirs[0].clone();
        for d in dirs.iter().skip(1) {
            let mut i = 0;
            while i < common.len() && i < d.len() && common[i] == d[i] {
                i += 1;
            }
            common.truncate(i);
        }
        if !common.is_empty() {
            return common.join("/");
        }
    }

    std::env::current_dir()
        .map(|p| p.to_string_lossy().replace('\\', "/"))
        .unwrap_or_else(|_| ".".to_string())
}

/// Turn an absolute or project-relative path into a path relative to `root`.
fn relativize(path: &str, root: &str) -> String {
    let p = normalize(path);
    let r = normalize(root).trim_end_matches('/').to_string();

    if r.is_empty() {
        return p.trim_start_matches("./").to_string();
    }
    if p == r {
        return String::new();
    }
    if let Some(rest) = p.strip_prefix(&format!("{}/", r)) {
        return rest.to_string();
    }
    // Case-insensitive prefix match (Windows drive letters / casing).
    let pl = p.to_lowercase();
    let rl = r.to_lowercase();
    if let Some(rest) = pl.strip_prefix(&format!("{}/", rl)) {
        return p[p.len() - rest.len()..].to_string();
    }
    // Fallback: strip everything up to the last component of the project root.
    if let Some(last) = r.rsplit('/').next() {
        let needle = format!("{}/", last.to_lowercase());
        if let Some(idx) = pl.find(&needle) {
            return p[idx + needle.len()..].to_string();
        }
    }
    // Last resort.
    if !p.starts_with('/') && !p.contains(':') {
        p.trim_start_matches("./").to_string()
    } else {
        p.rsplit('/').next().unwrap_or(&p).to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_staging_roundtrip() {
        clear_staging();
        stage_file("Pictures/app/index.html", "<html></html>");
        stage_file("Pictures\\app\\app.js", "console.log(1)");

        // Other tests (`write_file` / `edit_file`) stage files in parallel, so we
        // assert on our own keys instead of the total count.
        let files = staged_files();
        assert!(files.iter().any(|(p, _)| p == "Pictures/app/index.html"));
        assert!(
            files
                .iter()
                .any(|(p, c)| p == "Pictures/app/app.js" && c == "console.log(1)")
        );

        // Latest content wins for the same normalized key.
        stage_file("Pictures/app/app.js", "console.log(2)");
        let files = staged_files();
        let js: Vec<_> = files
            .iter()
            .filter(|(p, _)| p == "Pictures/app/app.js")
            .collect();
        assert_eq!(js.len(), 1);
        assert_eq!(js[0].1, "console.log(2)");
    }

    #[test]
    fn test_relativize_prefix() {
        assert_eq!(
            relativize(
                "C:/Users/x/Pictures/app/index.html",
                "C:/Users/x/Pictures/app"
            ),
            "index.html"
        );
        assert_eq!(
            relativize("Pictures/app/src/main.js", "Pictures/app"),
            "src/main.js"
        );
        // Case-insensitive fallback.
        assert_eq!(
            relativize("c:/users/x/pictures/app/a.js", "C:/Users/x/Pictures/app"),
            "a.js"
        );
        // Last-component fallback.
        assert_eq!(
            relativize("D:/other/app/lib/a.js", "C:/Users/x/app"),
            "lib/a.js"
        );
    }

    #[test]
    fn test_determine_project_root() {
        let staged = vec![
            ("Pictures/app/index.html".to_string(), String::new()),
            ("Pictures/app/src/main.js".to_string(), String::new()),
        ];
        assert_eq!(determine_project_root(None, &staged), "Pictures/app");
        assert_eq!(
            determine_project_root(Some("./mon/projet"), &staged),
            "mon/projet"
        );
    }

    #[test]
    fn test_detect_commands_cargo() {
        let dir = std::env::temp_dir().join(format!("rv_cargo_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("Cargo.toml"), "[package]\nname=\"x\"").unwrap();
        let cmds = detect_commands(&dir);
        assert_eq!(
            cmds,
            vec![
                "cargo check --quiet".to_string(),
                "cargo test --quiet".to_string()
            ]
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn test_detect_commands_npm_test_script() {
        let dir = std::env::temp_dir().join(format!("rv_npm_test_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();

        // A real test script is included...
        std::fs::write(
            dir.join("package.json"),
            "{\"scripts\":{\"build\":\"vite build\",\"test\":\"vitest run\"}}",
        )
        .unwrap();
        let cmds = detect_commands(&dir);
        assert!(
            cmds.iter().any(|c| c == "npm test --silent"),
            "cmds: {:?}",
            cmds
        );

        // ...but the `npm init` placeholder is not.
        std::fs::write(
            dir.join("package.json"),
            "{\"scripts\":{\"test\":\"echo \\\"Error: no test specified\\\" && exit 1\"}}",
        )
        .unwrap();
        let cmds = detect_commands(&dir);
        assert!(
            !cmds.iter().any(|c| c.starts_with("npm test")),
            "cmds: {:?}",
            cmds
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn test_detect_commands_python_tests() {
        let dir = std::env::temp_dir().join(format!("rv_py_test_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("tests")).unwrap();
        std::fs::write(dir.join("main.py"), "print('hi')\n").unwrap();
        std::fs::write(
            dir.join("tests").join("test_x.py"),
            "def test_ok():\n    assert True\n",
        )
        .unwrap();
        let cmds = detect_commands(&dir);
        assert!(
            cmds.iter().any(|c| c == "python -m unittest discover -q"),
            "cmds: {:?}",
            cmds
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn test_detect_commands_node_build() {
        let dir = std::env::temp_dir().join(format!("rv_node_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(
            dir.join("package.json"),
            "{\"scripts\":{\"build\":\"vite build\"}}",
        )
        .unwrap();
        let cmds = detect_commands(&dir);
        assert!(cmds.iter().any(|c| c.starts_with("npm install")));
        assert!(cmds.iter().any(|c| c == "npm run build"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn test_detect_commands_plain_js() {
        let dir = std::env::temp_dir().join(format!("rv_js_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("app.js"), "console.log(1);").unwrap();
        let cmds = detect_commands(&dir);
        assert_eq!(cmds.len(), 1);
        assert!(cmds[0].contains("node --check app.js"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    async fn node_available() -> bool {
        crate::tools::run_shell_command_capture("node --version", None, Duration::from_secs(10))
            .await
            .0
    }

    /// End-to-end: valid JS passes, broken JS is reported as a failure. Skipped
    /// when `node` is not installed so the test suite stays portable.
    #[tokio::test]
    async fn test_run_verification_end_to_end() {
        if !node_available().await {
            return;
        }
        let base = std::env::temp_dir().join(format!("rv_e2e_{}", std::process::id()));
        let ok_dir = base.join("ok");
        let bad_dir = base.join("bad");
        let _ = std::fs::remove_dir_all(&base);
        // Best-effort: avoid inheriting files staged by concurrently running tests.
        clear_staging();

        std::fs::create_dir_all(&ok_dir).unwrap();
        std::fs::write(ok_dir.join("app.js"), "const a = 1;\nconsole.log(a);\n").unwrap();

        std::fs::create_dir_all(&bad_dir).unwrap();
        std::fs::write(bad_dir.join("app.js"), "const a = ;\n").unwrap();

        let ok_report = run_verification(Some(ok_dir.to_str().unwrap())).await;
        assert!(
            ok_report.contains("OK ✅"),
            "rapport inattendu: {}",
            ok_report
        );

        let bad_report = run_verification(Some(bad_dir.to_str().unwrap())).await;
        assert!(
            bad_report.contains("ÉCHEC ❌"),
            "rapport inattendu: {}",
            bad_report
        );

        let _ = std::fs::remove_dir_all(&base);
    }

    /// The streaming variant must emit the command (before running) and its
    /// output, so the UI can display the execution like a terminal.
    #[tokio::test]
    async fn test_run_verification_streams_commands() {
        if !node_available().await {
            return;
        }
        let dir = std::env::temp_dir().join(format!("rv_stream_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("app.js"), "const a = 1;\n").unwrap();

        let mut streamed = String::new();
        let report = run_verification_streaming(Some(dir.to_str().unwrap()), |chunk| {
            streamed.push_str(chunk);
        })
        .await;

        assert!(
            streamed.contains("$ node --check app.js"),
            "commande absente du flux: {}",
            streamed
        );
        assert!(
            streamed.contains("Statut (bash)"),
            "sortie absente du flux: {}",
            streamed
        );
        assert!(report.contains("OK ✅"), "rapport inattendu: {}", report);

        let _ = std::fs::remove_dir_all(&dir);
    }
}
